const leads = $('Haftalık Lead Dağılımı').all();
const sys = $('Sistem Sağlık Metrikleri').first()?.json || {};

const typeLabels = {
  quote: '📋 Yönetim Teklif Talebi',
  callback: '🔔 Geri Arama',
  contact: '📞 İletişim',
  newsletter: '📧 E-Bülten'
};

let totalLeads = 0;
const leadRows = leads.map(item => {
  const cnt = parseInt(item.json.count, 10) || 0;
  totalLeads += cnt;
  const label = typeLabels[item.json.type] || item.json.type;
  return `<tr><td style="padding: 8px; border-bottom: 1px solid #e2e8f0;">${label}</td><td style="padding: 8px; text-align: center; font-weight: bold; border-bottom: 1px solid #e2e8f0;">${cnt}</td></tr>`;
}).join('');

const unreadLeads = parseInt(sys.unread_leads || 0, 10);
const incidents = parseInt(sys.weekly_incidents || 0, 10);
const errors = parseInt(sys.weekly_errors || 0, 10);
const dbSize = sys.db_size || 'Bilinmiyor';
const livePosts = sys.live_posts || 0;
const liveReferences = sys.live_references || 0;

const slaStatus = incidents === 0 ? '%99.99 (Kusursuz)' : `%${(100 - incidents * 0.1).toFixed(2)}`;

const reportTime = new Date().toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

return [{
  json: {
    totalLeads,
    unreadLeads,
    incidents,
    errors,
    dbSize,
    livePosts,
    liveReferences,
    slaStatus,
    leadRows,
    reportTime,
    summary: `Haftalık Kokpit: ${totalLeads} Yeni Lead | ${unreadLeads} Bekleyen | ${incidents} Kesinti | SLA: ${slaStatus}`
  }
}];
